import { Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Switch from "../../ui/shadcn-switch";

// MODEL

export const Model = S.Struct({
  switchModel: Switch.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotSwitchMessage = m("GotSwitchMessage", {
  message: Switch.Message,
});

export const Message = S.Union([GotSwitchMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [switchModel, switchCommands] = Switch.init({
    id: "shadcn-switch-basic",
  });

  return [
    { switchModel },
    Command.mapMessages(switchCommands, (message) =>
      GotSwitchMessage({ message })
    ),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotSwitchMessage: ({ message }) => {
        const [switchModel, switchCommands] = Switch.update(
          model.switchModel,
          message
        );

        return [
          evo(model, { switchModel: () => switchModel }),
          Command.mapMessages(switchCommands, (message) =>
            GotSwitchMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("flex items-center space-x-2")],
    [
      h.submodel({
        slotId: model.switchModel.id,
        model: model.switchModel,
        view: Switch.view,
        viewInputs: {
          toView: (attributes) =>
            h.div(
              [h.Class("flex items-center space-x-2")],
              [
                h.button(
                  [
                    ...attributes.button,
                    h.Class(Switch.shadcnSwitchButtonClasses),
                  ],
                  [Switch.shadcnSwitchKnob(model.switchModel.isChecked)]
                ),
                h.label(
                  [
                    ...attributes.label,
                    h.Class(Switch.shadcnSwitchLabelClasses),
                  ],
                  ["Airplane Mode"]
                ),
              ]
            ),
        },
        toParentMessage: (message) => GotSwitchMessage({ message }),
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as ShadcnSwitchBasicExample from "./main";

describe("shadcn Switch Basic example", () => {
  test("renders the origin Airplane Mode switch", () => {
    Scene.scene(
      {
        update: ShadcnSwitchBasicExample.update,
        view: ShadcnSwitchBasicExample.view,
      },
      Scene.with(ShadcnSwitchBasicExample.init()[0]),
      Scene.expect(Scene.role("switch", { name: "Airplane Mode" })).toExist(),
      Scene.expect(Scene.text("Email alerts")).not.toExist(),
      Scene.click(Scene.role("switch", { name: "Airplane Mode" })),
      Scene.expect(
        Scene.role("switch", { name: "Airplane Mode" })
      ).toBeChecked()
    );
  });
});
